const esc = value => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

const visual = (after, type, title, question, takeaway, data = {}) => ({ after, type, title, question, takeaway, ...data });

