const header = visualItem => {
  const id = `teaching-visual-${visualItem.after.replace(".", "-")}`;
  return `<header class="tv-head"><p>SECTION ${esc(visualItem.after)} · SEE THE MECHANISM</p><h4 id="${id}">${esc(visualItem.title)}</h4><span>${esc(visualItem.question)}</span></header>`;
};

const node = (label, extra = "") => `<li${extra ? ` class="${extra}"` : ""}><strong>${esc(label)}</strong></li>`;

function renderCompare(item) {
  return `<div class="tv-compare">${item.lanes.map(lane => `<section${lane.loop ? ' class="is-loop"' : ""}><h5>${esc(lane.label)}</h5><ol>${lane.steps.map(step => node(step)).join("")}</ol>${lane.loop ? '<span class="tv-return">inspect ↺ continue</span>' : ""}</section>`).join("")}</div>`;
}

function renderPipeline(item) {
  return `<ol class="tv-pipeline">${item.steps.map((step, index) => node(step, index === item.emphasis ? "is-human" : "")).join("")}</ol>${item.badge ? `<p class="tv-badge">${esc(item.badge)}</p>` : ""}${item.risk ? '<p class="tv-risk">Each handoff can introduce a different error</p>' : ""}`;
}

function renderCycle(item) {
  return `<div class="tv-cycle"><ol>${item.steps.map((step, index) => `<li style="--i:${index}"><span>${index + 1}</span><strong>${esc(step)}</strong></li>`).join("")}</ol><div class="tv-cycle-core" aria-hidden="true">↻</div><p class="tv-cycle-warning">${esc(item.warning || "REPEAT")}</p></div>`;
}

function renderBody(item) {
  switch (item.type) {
    case "nested": return `<div class="tv-nested">${item.layers.map(([label, detail], index) => `<section style="--depth:${index}"><strong>${esc(label)}</strong><span>${esc(detail)}</span></section>`).join("")}</div>`;
    case "timeline": return `<div class="tv-timeline"><div class="tv-forces">${item.forces.map(force => `<span>${esc(force)}</span>`).join("")}<b>CONVERGE ↓</b></div><ol>${item.events.map(([date, label]) => `<li><time>${esc(date)}</time><strong>${esc(label)}</strong></li>`).join("")}</ol></div>`;
    case "compare": return renderCompare(item);
    case "pipeline": return renderPipeline(item);
    case "triad": return `<div class="tv-triad"><div>${item.sources.map(([label, detail]) => `<section><strong>${esc(label)}</strong><span>${esc(detail)}</span></section>`).join("")}</div><b aria-hidden="true">→</b><strong class="tv-target">${esc(item.target)}</strong></div>`;
    case "cycle": return renderCycle(item);
    case "tokenise": return `<div class="tv-tokenise"><section><span>FAMILIAR</span><p><b>play</b><b>ground</b></p><small>2 reusable pieces</small></section><section><span>UNUSUAL</span><p><b>re</b><b>tro</b><b>fu</b><b>tur</b><b>ism</b></p><small>5 smaller pieces</small></section><div class="tv-token-rule">same letters are not promised the same split</div></div>`;
    case "container": return `<div class="tv-container"><div class="tv-window"><strong>CONTEXT WINDOW · LIMITED CAPACITY</strong><span class="tv-slot tv-instructions">Instructions</span><span class="tv-slot tv-message">Your message</span><span class="tv-slot tv-history">Selected history</span><span class="tv-slot tv-docs">Retrieved documents</span></div><div class="tv-overflow"><span>MORE MATERIAL ARRIVES</span><b>↓</b><strong>omit · summarise · or stop</strong></div></div>`;
    case "converge": return `<div class="tv-converge"><div>${item.inputs.map(([label, detail]) => `<section><strong>${esc(label)}</strong><span>${esc(detail)}</span></section>`).join("")}</div><b class="tv-funnel">↓</b><p>${esc(item.output)}</p><ol>${[148, 32, 901, 76, 14, 522].map(value => `<li>${value}</li>`).join("")}</ol></div>`;
    case "network": return `<div class="tv-network" role="img" aria-label="Numbers pass through connected mathematical layers to an output"><div class="tv-network-labels"><span>INPUT NUMBERS</span><span>PATTERN LAYERS</span><span>OUTPUT</span></div><svg viewBox="0 0 720 250" aria-hidden="true"><g class="lines">${[45,105,165,225].flatMap(y1 => [50,125,200].map(y2 => `<line x1="90" y1="${y1}" x2="300" y2="${y2}"/>`)).join("")}${[50,125,200].flatMap(y1 => [70,145,220].map(y2 => `<line x1="330" y1="${y1}" x2="540" y2="${y2}"/>`)).join("")}${[70,145,220].map(y => `<line x1="570" y1="${y}" x2="675" y2="125"/>`).join("")}</g><g class="nodes">${[45,105,165,225].map(y => `<circle cx="75" cy="${y}" r="17"/>`).join("")}${[50,125,200].map(y => `<circle cx="315" cy="${y}" r="21"/>`).join("")}${[70,145,220].map(y => `<circle cx="555" cy="${y}" r="21"/>`).join("")}<circle cx="690" cy="125" r="25"/></g></svg><p>Each connection carries a learned numerical weight. A whole pattern is spread across many connections.</p></div>`;
    case "attention": return `<div class="tv-attention"><p class="tv-sentence"><span>The</span><span>trophy</span><span>didn't fit</span><span>in the suitcase</span><span>because</span><span class="is-current">it</span><span>was too big.</span></p><svg viewBox="0 0 760 170" role="img" aria-label="The word it has a strong attention link to trophy and a weaker link to suitcase"><path class="weak" d="M460 130 Q510 30 565 130"/><path class="strong" d="M135 130 Q350 -10 565 130"/></svg><div class="tv-attention-legend" aria-hidden="true"><span class="strong">THICK LINE · STRONGER LINK</span><span class="weak">THIN LINE · WEAKER LINK</span></div><p class="tv-attention-answer"><b>“it”</b> is more strongly connected to <b>“trophy”</b> than <b>“suitcase.”</b></p></div>`;
    case "patches": return `<div class="tv-patches"><div class="tv-mini-photo"><img src="assets/ch06-bicycle-tree-learning-image.png" alt="A purple bicycle parked beside a leafy tree"></div><b aria-hidden="true">→</b><div class="tv-patch-grid">${Array.from({ length: 24 }, (_, index) => `<i style="--n:${index}"></i>`).join("")}</div><b aria-hidden="true">→</b><div class="tv-features"><span>edges</span><span>colours</span><span>shapes</span><span>relationships</span></div><b aria-hidden="true">→</b><strong class="tv-result">TASK RESULT<br><small>“a bicycle near a tree”</small></strong></div>`;
    case "diffusion": return `<div class="tv-diffusion"><section class="stage-0"><div class="tv-noise-grid">${Array.from({ length: 64 }, (_, dot) => `<i style="background:hsl(${(dot * 47) % 360} 58% ${28 + (dot % 5) * 13}%)"></i>`).join("")}</div><strong>NOISE</strong></section>${[["ROUGH SHAPES", "stage-1"], ["DETAIL EMERGES", "stage-2"], ["COHERENT IMAGE", "stage-3"]].map(([label, stage]) => `<section class="${stage}"><div class="tv-denoise-image"><img src="assets/ch06-bicycle-tree-learning-image.png" alt=""></div><strong>${label}</strong></section>`).join("")}</div>`;
    case "sampling": return `<div class="tv-sampling"><p>“For the picnic, bring a…”</p><div class="tv-candidates"><span style="--p:92%"><b>blanket</b><i>92%</i></span><span style="--p:61%"><b>basket</b><i>61%</i></span><span style="--p:34%"><b>speaker</b><i>34%</i></span><span style="--p:18%"><b>camera</b><i>18%</i></span></div><div class="tv-choice"><section><b>LOWER VARIATION</b><span>mostly chooses near the top</span></section><section><b>HIGHER VARIATION</b><span>allows more of the plausible set</span></section></div></div>`;
    case "timing": return `<div class="tv-timing"><section><h5>INPUT · TOGETHER</h5><div class="parallel"><i>Plan</i><i>a</i><i>weekend</i><i>in</i><i>Montreal</i></div><span>processed in parallel</span></section><section><h5>OUTPUT · ONE AFTER ANOTHER</h5><div class="sequential"><i>Start</i><i>with</i><i>the</i><i>Old</i><i>Port…</i></div><span>each new piece depends on the last</span></section></div>`;
    case "memory": return `<div class="tv-memory"><section class="tv-store"><strong>OUTSIDE THE MODEL</strong><span>saved conversation</span><span>optional memory</span></section><b>load selected material →</b><section class="tv-current-context"><strong>CURRENT CONTEXT</strong><span>instructions</span><span>new message</span><span>selected history</span></section><b>→</b><section class="tv-frozen-model"><strong>FROZEN MODEL</strong><span>calculates response</span><small>does not keep the conversation inside itself</small></section></div>`;
    case "similarity": return `<div class="tv-similarity"><div class="tv-space" role="img" aria-label="Meaningfully similar phrases appear near one another while unrelated phrases appear farther away"><span class="point p1">easy dinner</span><span class="point p2">quick supper</span><span class="point p3">weeknight meal</span><span class="point p4">tax return</span><span class="point p5">quarterly filing</span><span class="point query">QUERY: fast evening recipe</span></div><p>Near = similar pattern of use. It does not mean true, good or identical.</p></div>`;
    case "rag": return `<div class="tv-rag"><section class="tv-question">QUESTION</section><b>→ search →</b><section class="tv-library"><strong>APPROVED SOURCES</strong><span class="is-hit">relevant passage</span><span>other passage</span><span class="is-hit">relevant passage</span></section><b>→ add selected passages →</b><section class="tv-context-model"><div>THIS REQUEST'S CONTEXT</div><strong>UNCHANGED MODEL</strong><span>answer grounded in retrieved material</span></section></div>`;
    case "ladder": return `<ol class="tv-ladder">${item.steps.map(([number, label], index) => `<li style="--level:${index}"><span>${esc(number)}</span><strong>${esc(label)}</strong><small>${index === 0 ? "cheapest · fastest · easiest to undo" : index === item.steps.length - 1 ? "costliest · slowest · most permanent" : ""}</small></li>`).join("")}</ol>`;
    case "stack": return `<div class="tv-stack">${item.layers.map(([label, detail], index) => `<section style="--layer:${index}"><strong>${esc(label)}</strong><span>${esc(detail)}</span></section>`).join("")}</div>`;
    case "orchestrate": return `<div class="tv-orchestrate"><section class="tv-request">REQUEST</section><b>→</b><section class="tv-router">ROUTE + CHECK LIMITS</section><div class="tv-tool-ring"><span>MODEL</span><span>DATA</span><span>TOOL</span></div><b>→</b><section class="tv-check">COMBINE + CHECK</section><div class="tv-outcomes"><span>answer</span><span>ask approval</span><span>retry</span><span>stop</span></div></div>`;
    case "safety": return `<div class="tv-safety"><ol><li><span>1</span><strong>INPUT RULES</strong><small>screen the request</small></li><li><span>2</span><strong>MODEL BEHAVIOUR</strong><small>shape likely responses</small></li><li><span>3</span><strong>OUTPUT CHECKS</strong><small>inspect before delivery</small></li><li><span>4</span><strong>MONITORING + POLICY</strong><small>catch patterns and respond</small></li></ol><div class="tv-safety-flow"><b>REQUEST</b><i>→</i><b>MODEL</b><i>→</i><b>RESULT</b></div></div>`;
    case "sandbox": return `<div class="tv-sandbox"><div class="tv-outside"><span>private files</span><span>other accounts</span><span>unapproved internet</span><span>payment system</span></div><section><header>SANDBOX BOUNDARY</header><div class="tv-proposal">AI PROPOSES ACTION</div><b>↓ permission check</b><div class="tv-approved"><span>approved tool</span><span>temporary files</span><span>bounded network</span></div><b>↓</b><div class="tv-execute">RUN · LOG · RETURN RESULT</div></section><p>blocked unless explicitly allowed</p></div>`;
    case "spectrum": return `<div class="tv-spectrum"><div class="tv-spectrum-axis"><span>easy to undo</span><b>REVERSIBILITY FALLS →</b><span>hard to undo</span></div><ol>${item.levels.map(([label, detail, approval], index) => `<li style="--risk:${index}"><strong>${esc(label)}</strong><span>${esc(detail)}</span><b>${esc(approval)}</b></li>`).join("")}</ol><div class="tv-approval-line">HUMAN APPROVAL MOVES EARLIER ↑</div></div>`;
    case "toolcall": return `<div class="tv-toolcall"><section class="tv-model-proposal"><strong>MODEL</strong><span>“use calendar.create”</span><small>proposes a tool + arguments</small></section><b>→</b><section class="tv-harness"><strong>APPLICATION HARNESS</strong><span>validate fields</span><span>check identity</span><span>check scope + permission</span></section><b>→</b><section class="tv-tool"><strong>APPROVED TOOL</strong><span>runs or refuses</span><small>result + log return</small></section><div class="tv-tool-return">result returns to context ↺</div></div>`;
    case "multiagent": return `<div class="tv-multiagent"><section class="tv-coordinator"><strong>COORDINATOR</strong><span>split bounded jobs</span></section><div class="tv-specialists"><section><strong>SOURCE CHECK</strong><span>facts + evidence</span></section><section><strong>TEACHING</strong><span>plain explanation</span></section><section><strong>FORMAT</strong><span>surface fit</span></section></div><div class="tv-evidence-return">evidence returns ↑</div><section class="tv-reconcile"><strong>RECONCILE</strong><span>resolve overlap · conflicts · missing proof</span></section><section class="tv-one-output">ONE FINAL OUTPUT</section></div>`;
    case "parallel": return `<div class="tv-parallel"><section><h5>CPU · SHORT QUEUE</h5><div class="tv-cpu-line">${Array.from({ length: 12 }, (_, index) => `<i>${index + 1}</i>`).join("")}</div><span>one calculation waits behind another</span></section><section><h5>GPU · MANY AT ONCE</h5><div class="tv-gpu-grid">${Array.from({ length: 24 }, (_, index) => `<i>${index + 1}</i>`).join("")}</div><span>similar calculations spread across many cores</span></section></div>`;
    case "gpuwork": return `<div class="tv-gpuwork"><section class="tv-data-split"><strong>TRAINING BATCH</strong><div><span>A</span><span>B</span><span>C</span><span>D</span></div></section><b>split ↓</b><div class="tv-gpus"><section>GPU 1<small>forward + loss</small></section><section>GPU 2<small>forward + loss</small></section><section>GPU 3<small>forward + loss</small></section><section>GPU 4<small>forward + loss</small></section></div><div class="tv-sync">↔ EXCHANGE GRADIENTS ↔<small>network + memory movement can make chips wait</small></div><section class="tv-update">COMBINE UPDATE → NEXT ROUND ↺</section></div>`;
    case "datacenter": return `<div class="tv-datacenter"><div class="tv-dc-building"><header>DATA CENTRE</header><section class="tv-dc-network"><strong>NETWORK</strong><span>request arrives</span></section><section class="tv-dc-cpu"><strong>CPU SERVERS</strong><span>route + coordinate</span></section><section class="tv-dc-gpu"><strong>GPU RACKS</strong><span>run model calculations</span></section><section class="tv-dc-memory"><strong>MEMORY + STORAGE</strong><span>move model data</span></section><section class="tv-dc-power"><strong>POWER IN</strong><span>electricity + conversion</span></section><section class="tv-dc-cooling"><strong>COOLING</strong><span>heat out ↺ coolant returns</span></section></div><div class="tv-dc-route"><span>YOUR DEVICE</span><b>request →</b><span>PHYSICAL COMPUTE</span><b>→ response</b></div></div>`;
    case "supplychain": return `<div class="tv-supplychain"><ol><li><b class="tv-step-number">1</b><small>GLOBAL</small><strong>MATERIALS</strong><span>silicon + minerals</span></li><li class="is-choke"><b class="tv-step-number">2</b><small>NETHERLANDS</small><strong>EUV EQUIPMENT</strong><span>one highly concentrated supplier</span></li><li class="is-choke"><b class="tv-step-number">3</b><small>TAIWAN</small><strong>ADVANCED FAB</strong><span>leading-edge manufacturing</span></li><li class="is-choke"><b class="tv-step-number">4</b><small>SOUTH KOREA</small><strong>HBM MEMORY</strong><span>specialist high-bandwidth memory</span></li><li class="is-choke"><b class="tv-step-number">5</b><small>ASIA + US</small><strong>PACKAGING</strong><span>join chip + memory</span></li><li><b class="tv-step-number">6</b><small>WORLDWIDE</small><strong>DATA CENTRE</strong><span>server integration + operation</span></li></ol><p>CHOKEPOINT = one concentrated stage can constrain the whole chain</p></div>`;
    case "euv": return `<div class="tv-euv"><section class="laser"><strong>POWERFUL LASER</strong><span>fires at a falling tin droplet</span></section><b>→</b><section class="plasma"><strong>TIN PLASMA</strong><span>creates extreme-ultraviolet light</span></section><b>→</b><section class="mirrors"><strong>PRECISION MIRRORS</strong><span>focus light in a vacuum</span></section><b>→</b><section class="mask"><strong>PATTERN MASK</strong><span>carries the chip design</span></section><b>→</b><section class="wafer"><strong>SILICON WAFER</strong><span>one microscopic layer is exposed</span></section></div>`;
    case "handoff": return `<div class="tv-handoff"><div class="tv-feature-start">ONE AI FEATURE</div><ol><li><b class="tv-step-number">1</b><strong>PRODUCT</strong><span>defines the real job</span></li><li><b class="tv-step-number">2</b><strong>DATA + LABELLERS</strong><span>prepare examples + judgments</span></li><li><b class="tv-step-number">3</b><strong>ML ENGINEERING</strong><span>train or integrate model</span></li><li><b class="tv-step-number">4</b><strong>CONTEXT + APP</strong><span>add instructions, tools + interface</span></li><li><b class="tv-step-number">5</b><strong>SAFETY + EVALS</strong><span>test limits + real-use failures</span></li><li><b class="tv-step-number">6</b><strong>MLOPS</strong><span>deploy, monitor + repair</span></li></ol><div class="tv-feedback">USER OUTCOME + FEEDBACK ↺ returns to product and data</div></div>`;
    case "agichain": return `<div class="tv-agichain"><section><h5>CURRENT AI CAN ASSIST WITH PIECES</h5><div class="tv-loose-pieces"><span>summarise</span><span>search</span><span>draft</span><span>code</span><span>analyse</span></div></section><section><h5>THE STRONGER AGI TEST IS A CONNECTED CHAIN</h5><ol><li>understand an unfamiliar problem</li><li>gather relevant evidence</li><li>form + test a plan</li><li>notice error + revise</li><li>act reliably across domains</li></ol></section></div>`;
    default: throw new Error(`unknown teaching visual type: ${item.type}`);
  }
}

export function renderTeachingVisual(item) {
  if (!item?.after) throw new Error("teaching visual is missing its section anchor");
  const id = `teaching-visual-${item.after.replace(".", "-")}`;
  return `<figure class="teaching-visual teaching-kind-${esc(item.type)}" data-teaching-section="${esc(item.after)}" aria-labelledby="${id}">${header(item)}<div class="tv-body">${renderBody(item)}</div><figcaption><strong>The point:</strong> ${esc(item.takeaway)}</figcaption></figure>`;
}

